mapper.select:
select m.id, m.sender_type as senderType,
       m.message_type as messageType, m.body, m.action_type as actionType,
       m.created_at as createdAt
from cm_inbox_messages m
where m.thread_id = #{threadId}

    and (
        not exists (
            select 1 from cm_inbox_messages cursor_message
            where cursor_message.id = #{before}
              and cursor_message.thread_id = #{threadId}
        )
        or m.created_at < (
            select cursor_message.created_at
            from cm_inbox_messages cursor_message
            where cursor_message.id = #{before}
              and cursor_message.thread_id = #{threadId}
        )
        or (
            m.created_at = (
                select cursor_message.created_at
                from cm_inbox_messages cursor_message
                where cursor_message.id = #{before}
                  and cursor_message.thread_id = #{threadId}
            )
            and m.id < #{before}
        )
    )

order by m.created_at desc, m.id desc
limit #{limit}

mapper.insert:
insert into cm_inbox_reads (
    id, thread_id, user_id, last_read_at, created_at, updated_at
) values (
    #{id}, #{threadId}, #{userId}, now(), now(), now()
) on duplicate key update last_read_at = now(), updated_at = now()
